function makePerspective(fovY, aspect, nearZ, farZ)
    local cot = 1/math.tan(fovY/2)
    return ccsphere_mat4(cot/aspect, 0,0,0,
            0, cot,0,0,
            0, 0,(farZ+nearZ)/(nearZ-farZ),-1,
            0, 0,(2*farZ*nearZ)/(nearZ-farZ),0)
end

function makeLookAt(eye, center, up)

    local forward = (eye-center):normalize()
    local side = (up:cross(forward)):normalize()
    local up = forward:cross(side)
    return ccsphere_mat4(side.x, up.x,forward.x,0,
            side.y, up.y,forward.y,0,
            side.z, up.z,forward.z,0,
            -side:dot(eye), -up:dot(eye),-forward:dot(eye),1)


